// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [1377413573, 2469513669, 1440807365, 4151656901, 276380101, 3350790597, 929403333, 3837671877, 128258501, 2831233477, 2887977413, 3733182917, 4158958021, 2650890693, 3265671621, 1109524933];
const blocks = ["NFD U+0B0000-U+0B0FFF", "NFD U+0B1000-U+0B1FFF", "NFD U+0B2000-U+0B2FFF", "NFD U+0B3000-U+0B3FFF", "NFD U+0B4000-U+0B4FFF", "NFD U+0B5000-U+0B5FFF", "NFD U+0B6000-U+0B6FFF", "NFD U+0B7000-U+0B7FFF", "NFD U+0B8000-U+0B8FFF", "NFD U+0B9000-U+0B9FFF", "NFD U+0BA000-U+0BAFFF", "NFD U+0BB000-U+0BBFFF", "NFD U+0BC000-U+0BCFFF", "NFD U+0BD000-U+0BDFFF", "NFD U+0BE000-U+0BEFFF", "NFD U+0BF000-U+0BFFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 720896 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
